const COMMENT_FONT_FAMILY = "CommentXingKai";
// 马善政楷书 — 传记批注/评语用字（内嵌子集 + CDN 全量兜底）
const FONT_SOURCES = [
  'url("data:font/woff2;base64,")',
  'url("https://cdn.jsdelivr.net/fontsource/fonts/ma-shan-zheng@5.2.5/chinese-simplified-400-normal.woff2")',
  'url("https://cdn.jsdelivr.net/fontsource/fonts/ma-shan-zheng@5.2.5/chinese-simplified-400-normal.woff")',
];

let loadPromise = null;

function loadCommentFont() {
  if (loadPromise) return loadPromise;

  loadPromise = new Promise((resolve) => {
    if (!wx.loadFontFace) {
      resolve(false);
      return;
    }

    let index = 0;
    const tryLoad = () => {
      if (index >= FONT_SOURCES.length) {
        resolve(false);
        return;
      }

      wx.loadFontFace({
        family: COMMENT_FONT_FAMILY,
        source: FONT_SOURCES[index],
        global: true,
        desc: {
          style: "normal",
          weight: "400",
          variant: "normal",
        },
        scopes: ["webview", "native"],
        success: () => resolve(true),
        fail: () => {
          index += 1;
          tryLoad();
        },
      });
    };

    tryLoad();
  });

  return loadPromise;
}

module.exports = {
  COMMENT_FONT_FAMILY,
  loadCommentFont,
};
